// Global State
let selectedFile = null;
let parsedData = null; // {'messages': [[ts, sender, content], ...], 'group_name': ...}
let detectedIsDM = false;
let selectedPeriod = "all"; // "all" (All Time) or "2026"

// Slide Deck State
let currentSlideIndex = 0;
let slidesList = [];
let activeCharts = [];
let calculatedStats = null;

// Obfuscated Profanity Blacklist (Base64)
const ENCODED_BLACKLIST = "";

// Escapes chat-derived text (names, words, emojis) before it goes into innerHTML,
// so a crafted group/contact name can't inject markup or trigger network requests.
function esc(value) {
    return String(value ?? "")
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
}

// UI State Helpers
function updateStepUI(stepId, state) {
    const el = document.getElementById(stepId);
    if (!el) return;
    const iconEl = el.querySelector(".step-icon");
    if (!iconEl) return;

    el.classList.remove("active", "completed");
    let stepNum = "1";
    if (stepId.includes("analyze")) stepNum = "2";
    else if (stepId.includes("charts")) stepNum = "3";

    if (state === "active") {
        el.classList.add("active");
        iconEl.innerText = "⚡";
    } else if (state === "completed") {
        el.classList.add("completed");
        iconEl.innerText = "✓";
    } else {
        iconEl.innerText = stepNum;
    }
}

function updateLineUI(lineId, completed) {
    const el = document.getElementById(lineId);
    if (!el) return;
    if (completed) el.classList.add("completed");
    else el.classList.remove("completed");
}

function setStepperDetail(text) {
    const el = document.getElementById("stepper-detail");
    if (el) el.innerText = text;
}

// Words of a message: Turkish-aware lowercase ("İYİ" -> "iyi", not "i̇yi̇"), split on anything that isn't a letter/digit
function splitWords(text) {
    return String(text || "").toLocaleLowerCase("tr").split(/[^\p{L}\p{N}_]+/u).filter(w => w.length > 0);
}

// Counter keyed by chat text: no prototype, so words like "constructor" or "__proto__" count like any other word
function newCounter() {
    return Object.create(null);
}

const EMOJI_REGEX = /[\u{1F300}-\u{1F64F}\u{1F680}-\u{1F6FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}\u{1F900}-\u{1F9FF}\u{1FA70}-\u{1FAFF}]/gu;

function formatDateForPdf(date) {
    if (!date) return '';
    const day = String(date.getDate()).padStart(2, '0');
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const year = date.getFullYear();
    return `${day}.${month}.${year}`;
}

// Dynamic Date Parser
// Date order of the loaded chat: "DMY" (Turkish/European exports) or "MDY" (English-US phone exports)
let chatDateOrder = "DMY";

// Looks at all timestamps of a chat: a first number > 12 means day-first, a second number > 12 means month-first
function detectDateOrder(timestamps) {
    let dayFirst = 0, monthFirst = 0;
    timestamps.forEach(ts => {
        const m = String(ts).match(/^\s*(\d{1,2})[./](\d{1,2})[./]\d{2,4}/);
        if (!m) return;
        const a = parseInt(m[1]), b = parseInt(m[2]);
        if (a > 12 && b <= 12) dayFirst++;
        else if (b > 12 && a <= 12) monthFirst++;
    });
    return monthFirst > dayFirst ? "MDY" : "DMY";
}

function parseDateString(str, order = chatDateOrder) {
    str = str.replace(/,/g, '').replace(/\s+/g, ' ').trim();
    let datePart = "";
    let timePart = "";
    let ampm = "";

    if (str.includes(' ')) {
        const parts = str.split(' ');
        datePart = parts[0];
        timePart = parts[1];
        if (parts[2]) ampm = parts[2].toUpperCase();
    } else {
        return null;
    }

    const dParts = datePart.split(/[./]/);
    if (dParts.length !== 3) return null;
    const first = parseInt(dParts[0]);
    const second = parseInt(dParts[1]);
    let year = parseInt(dParts[2]);
    if (year < 100) year += 2000;
    const day = order === "MDY" ? second : first;
    const month = (order === "MDY" ? first : second) - 1;

    let hours = 0, minutes = 0, seconds = 0;
    if (timePart.includes(':')) {
        const tParts = timePart.split(':');
        hours = parseInt(tParts[0]);
        minutes = parseInt(tParts[1]);
        if (tParts[2]) seconds = parseInt(tParts[2]);
    }

    if (ampm === 'PM' && hours < 12) hours += 12;
    if (ampm === 'AM' && hours === 12) hours = 0;

    const d = new Date(year, month, day, hours, minutes, seconds);
    if (isNaN(d.getTime())) return null;
    // new Date() silently rolls invalid values over (month 25 -> 2 years later); reject those instead
    if (d.getFullYear() !== year || d.getMonth() !== month || d.getDate() !== day) return null;
    return d;
}

function parseLineString(line, index) {
    line = line.trim();
    if (!line) return null;

    let timestamp = null;
    let sender = null;
    let content = null;

    if (line.startsWith('[')) {
        // iOS Format: [DD.MM.YYYY HH:MM:SS] Sender: Content
        if (line.includes('] ')) {
            const parts = line.split('] ');
            timestamp = parts[0].substring(1);
            const message = parts.slice(1).join('] ');
            if (message.includes(': ')) {
                const mParts = message.split(': ');
                sender = mParts[0];
                content = mParts.slice(1).join(': ');
            } else {
                sender = "System";
                content = message;
            }
        }
    } else if (line.includes(' - ')) {
        // Android Format: DD.MM.YYYY HH:MM - Sender: Content
        const parts = line.split(' - ');
        timestamp = parts[0];
        const message = parts.slice(1).join(' - ');
        if (message.includes(': ')) {
            const mParts = message.split(': ');
            sender = mParts[0];
            content = mParts.slice(1).join(': ');
        } else {
            sender = "System";
            content = message;
        }
    }

    if (timestamp && sender && content && TIMESTAMP_START.test(timestamp)) {
        return { timestamp, sender, content };
    }
    return null;
}

const TIMESTAMP_START = /^\s*\d{1,2}[./]\d{1,2}[./]\d{2,4}/;
const ENCRYPTION_NOTICE = /uçtan uca şifrelidir|end-to-end encrypted/i;

// Whole export -> message list. Lines that don't start with a timestamp belong to the previous (multi-line) message;
// lines starting with an invisible direction mark (iOS media/deleted notices) are skipped as before.
function parseChatText(textContent) {
    const lines = [];
    let noticeSender = null;

    textContent.split(/\r?\n/).forEach((line, idx) => {
        const parsed = parseLineString(line, idx);
        if (parsed) {
            if (lines.length <= 2 && ENCRYPTION_NOTICE.test(parsed.content)) {
                // The notice is not a message. In groups its sender is the group name, in DMs the contact.
                if (parsed.sender !== "System") noticeSender = parsed.sender.trim();
                return;
            }
            lines.push(parsed);
        } else {
            const trimmed = line.trim();
            const isContinuation = lines.length > 0 && trimmed
                && !/^[‎‏]/.test(trimmed)
                && !TIMESTAMP_START.test(trimmed.replace(/^\[/, ""));
            if (isContinuation) lines[lines.length - 1].content += "\n" + trimmed;
        }
    });

    // Group name only if the notice sender isn't one of two DM participants
    let groupName = null;
    if (noticeSender) {
        const others = new Set(lines.map(l => l.sender).filter(s => s !== "System" && s.trim() !== noticeSender));
        if (others.size >= 2) groupName = noticeSender;
    }

    chatDateOrder = detectDateOrder(lines.map(p => p.timestamp));
    return { lines, groupName };
}

function getLocalJSDateString(date) {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}

// Links (https://..., www..., youtube.com/...) are not words: strip them before any text analysis
const LINK_REGEX = /(?:https?:\/\/|www\.)\S+|\b[\w-]+(?:\.[\w-]+)*\.(?:com|net|org|io|me|tv|ly|gl|be|co|app|dev|edu|gov|info|xyz|link|tr)(?:\.[a-z]{2})?(?:\/\S*)?/gi;

// WhatsApp writes "<görsel dahil edilmedi>", "<GIF dahil edilmedi>", "<album mesajı>", "<Bu mesaj düzenlendi.>"
// in place of media/notes: anything between < and > is not something the person typed
function stripPlaceholders(text) {
    return String(text || "")
        .replace(/<[^<>]*>/g, " ")
        .replace(/[‎‏‪-‮⁦-⁩]/g, "")
        .replace(/\s{2,}/g, " ")
        .trim();
}

function stripLinks(text) {
    return String(text || "").replace(LINK_REGEX, " ").replace(/\s{2,}/g, " ").trim();
}

// Bot accounts are not group members: their messages are ignored in every statistic
const BOT_SENDERS = new Set(["meta ai"]);

function isBotSender(sender) {
    // Exports can wrap names in invisible direction marks (U+200E etc.)
    const clean = sender.replace(/[\u200e\u200f\u202a-\u202e\u2066-\u2069~]/g, '').trim().toLowerCase();
    return BOT_SENDERS.has(clean);
}

// 1:1 Stats Engine matching Python calculations
function calculateStats(rawMessages, groupName, userMap = {}, period = selectedPeriod) {
    let messages = rawMessages.map(m => {
        let sender = m.sender;
        if (Object.hasOwn(userMap, sender)) {
            sender = userMap[sender];
        }
        const withoutPlaceholders = stripPlaceholders(m.content);
        return {
            timestamp: m.timestamp,
            sender: sender,
            content: stripLinks(withoutPlaceholders),
            // Media-only messages ("<görsel dahil edilmedi>", "<album mesajı>", ...) are ignored entirely
            placeholderOnly: withoutPlaceholders === ""
        };
    });

    messages = messages.filter(m => !m.placeholderOnly && m.sender !== "System" && !m.sender.toLowerCase().includes("grubu") && m.sender !== groupName && !isBotSender(m.sender));

    const parsedMessages = [];
    messages.forEach(m => {
        let timeStr = m.timestamp.replace(/öğleden sonra/i, 'PM').replace(/öğleden önce/i, 'AM').trim();
        let dateObj = parseDateString(timeStr);
        if (dateObj) {
            parsedMessages.push({
                date: dateObj,
                sender: m.sender,
                content: m.content
            });
        }
    });

    // DM vs group is decided on the whole chat, so a group with only 2 active people in 2026 stays a group
    detectedIsDM = new Set(parsedMessages.map(m => m.sender)).size === 2;

    if (period === "2026") {
        const inPeriod = parsedMessages.filter(m => m.date.getFullYear() === 2026);
        parsedMessages.length = 0;
        parsedMessages.push(...inPeriod);
    }

    if (parsedMessages.length === 0) return null;

    // Senders list
    const sendersList = [...new Set(parsedMessages.map(m => m.sender))].sort();

    // A. Message Balance counts
    const messageCounts = {};
    sendersList.forEach(s => messageCounts[s] = 0);
    parsedMessages.forEach(m => { if (messageCounts[m.sender] !== undefined) messageCounts[m.sender]++; });
    const totalUsers = sendersList.length;
    const firstMsgDate = parsedMessages.length > 0 ? parsedMessages[0].date : null;
    const lastMsgDate = parsedMessages.length > 0 ? parsedMessages[parsedMessages.length - 1].date : null;
    const daysDiff = firstMsgDate && lastMsgDate ? ((lastMsgDate - firstMsgDate) / (24 * 3600 * 1000)) + 1 : 0;
    const dailyAvg = daysDiff > 0 ? parsedMessages.length / daysDiff : 0;
    const topMembers = [...sendersList].sort((a, b) => messageCounts[b] - messageCounts[a]);

    // B. Monthly Timeline (one bucket per calendar month from first to last message)
    const monthIndex = (d) => d.getFullYear() * 12 + d.getMonth();
    let minMonth = Infinity, maxMonth = -Infinity;
    parsedMessages.forEach(m => {
        const k = monthIndex(m.date);
        if (k < minMonth) minMonth = k;
        if (k > maxMonth) maxMonth = k;
    });
    const monthlyCounts = Array(maxMonth - minMonth + 1).fill(0);
    parsedMessages.forEach(m => { monthlyCounts[monthIndex(m.date) - minMonth]++; });
    const multiYear = Math.floor(minMonth / 12) !== Math.floor(maxMonth / 12);
    const monthLabels = monthlyCounts.map((_, i) => {
        const year = Math.floor((minMonth + i) / 12);
        const name = new Date(year, (minMonth + i) % 12, 1).toLocaleString('tr-TR', { month: 'short' });
        return multiYear ? `${name} '${String(year).slice(2)}` : name;
    });

    // C. Daily Activity
    const dailyCounts = Array(7).fill(0);
    parsedMessages.forEach(m => {
        const day = m.date.getDay();
        let idx = day - 1;
        if (idx < 0) idx = 6;
        dailyCounts[idx]++;
    });
    const dayLabels = ["Pazartesi", "Salı", "Çarşamba", "Perşembe", "Cuma", "Cumartesi", "Pazar"];

    // D. Hourly Activity
    const hourlyCounts = Array(24).fill(0);
    parsedMessages.forEach(m => { hourlyCounts[m.date.getHours()]++; });

    // Silent hours calculation (3 consecutive hours with minimum sum)
    let minSum = Infinity;
    let silentStartHour = 0;
    for (let i = 0; i < 24; i++) {
        const sum = hourlyCounts[i] + hourlyCounts[(i + 1) % 24] + hourlyCounts[(i + 2) % 24];
        if (sum < minSum) {
            minSum = sum;
            silentStartHour = i;
        }
    }
    const silentEndHour = (silentStartHour + 3) % 24;

    // E. Night Owls & Morning Birds
    const nightOwls = {};
    const morningBirds = {};
    sendersList.forEach(s => { nightOwls[s] = 0; morningBirds[s] = 0; });
    parsedMessages.forEach(m => {
        const hour = m.date.getHours();
        const minute = m.date.getMinutes();
        if (hour >= 0 && hour < 5) nightOwls[m.sender]++;
        else if ((hour >= 5 && hour < 9) || (hour === 9 && minute <= 30)) morningBirds[m.sender]++;
    });

    // F. First Message (hour >= 6, grouped by date)
    const firstMessagesByDate = {};
    parsedMessages.forEach(m => {
        if (m.date.getHours() >= 6) {
            const dateKey = getLocalJSDateString(m.date);
            if (!firstMessagesByDate[dateKey] || m.date < firstMessagesByDate[dateKey].date) {
                firstMessagesByDate[dateKey] = m;
            }
        }
    });

    const firstMsgWinnerCounts = {};
    sendersList.forEach(s => firstMsgWinnerCounts[s] = 0);
    Object.values(firstMessagesByDate).forEach(m => {
        if (firstMsgWinnerCounts[m.sender] !== undefined) firstMsgWinnerCounts[m.sender]++;
    });

    // G. First Responder
    // Group all messages by date
    const dailyMessages = {};
    parsedMessages.forEach(m => {
        if (m.date.getHours() >= 6) {
            const dateKey = getLocalJSDateString(m.date);
            if (!dailyMessages[dateKey]) dailyMessages[dateKey] = [];
            dailyMessages[dateKey].push(m);
        }
    });

    const firstResponderCounts = {};
    sendersList.forEach(s => firstResponderCounts[s] = 0);

    Object.values(dailyMessages).forEach(dayMsgs => {
        dayMsgs.sort((a, b) => a.date - b.date);
        if (dayMsgs.length >= 2) {
            const firstSender = dayMsgs[0].sender;
            for (let idx = 1; idx < dayMsgs.length; idx++) {
                const responder = dayMsgs[idx].sender;
                if (responder !== firstSender) {
                    if (firstResponderCounts[responder] !== undefined) firstResponderCounts[responder]++;
                    break;
                }
            }
        }
    });

    // H. Conversation Starter & Continuation (Session-based)
    // is_start definition: gap > 1 hour
    const silenceThreshold = 60 * 60 * 1000;
    const starterCounts = {};
    sendersList.forEach(s => starterCounts[s] = 0);

    // Sort chronologically
    const sortedMsgs = [...parsedMessages].sort((a, b) => a.date - b.date);

    let startIndices = [];
    sortedMsgs.forEach((m, idx) => {
        let isStart = false;
        if (idx === 0) {
            isStart = true;
        } else {
            const gap = m.date - sortedMsgs[idx - 1].date;
            if (gap > silenceThreshold) {
                isStart = true;
            }
        }
        if (isStart) {
            startIndices.push(idx);
            if (starterCounts[m.sender] !== undefined) starterCounts[m.sender]++;
        }
    });

    // Average continuation (conversation length) per sender
    const conversationLengths = {};
    sendersList.forEach(s => conversationLengths[s] = []);

    startIndices.forEach((startIdx, i) => {
        const nextStartIdx = (i === startIndices.length - 1) ? sortedMsgs.length : startIndices[i + 1];
        const length = nextStartIdx - startIdx;
        const sender = sortedMsgs[startIdx].sender;
        if (conversationLengths[sender] !== undefined) {
            conversationLengths[sender].push(length);
        }
    });

    const continuationAverages = {};
    sendersList.forEach(s => {
        const lengths = conversationLengths[s];
        if (lengths.length > 0) {
            const sum = lengths.reduce((a, b) => a + b, 0);
            continuationAverages[s] = (sum / lengths.length).toFixed(1);
        } else {
            continuationAverages[s] = 0;
        }
    });

    // I. Wordy Person (Average characters per message)
    const charCounts = {};
    const wordCounts = {};
    sendersList.forEach(s => {
        charCounts[s] = 0;
        wordCounts[s] = 0;
    });
    parsedMessages.forEach(m => {
        charCounts[m.sender] += m.content.length;
        const words = m.content.split(/\s+/).filter(w => w.length > 0).length;
        wordCounts[m.sender] += words;
    });
    const avgWords = {};
    sendersList.forEach(s => {
        avgWords[s] = messageCounts[s] > 0 ? (charCounts[s] / messageCounts[s]).toFixed(1) : 0;
    });

    // J. Emoji & Punctuation analysis
    const emojiCounts = newCounter();
    const punctuationCounts = { '?': 0, '!': 0, '.': 0, ',': 0 };

    parsedMessages.forEach(m => {
        // Emojis
        const emojis = m.content.match(EMOJI_REGEX);
        if (emojis) {
            emojis.forEach(e => {
                emojiCounts[e] = (emojiCounts[e] || 0) + 1;
            });
        }
        // Punctuation
        for (let char of m.content) {
            if (punctuationCounts[char] !== undefined) {
                punctuationCounts[char]++;
            }
        }
    });

    const topEmojis = Object.entries(emojiCounts)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 10);

    // K. Caps Lock Champion (Screaming count)
    const capslockCounts = {};
    sendersList.forEach(s => capslockCounts[s] = 0);
    parsedMessages.forEach(m => {
        // Letters only; scripts without upper/lower case (Arabic, CJK...) never count as shouting
        const cleaned = m.content.replace(/[^\p{L}]/gu, '');
        if (cleaned.length > 3 && cleaned === cleaned.toLocaleUpperCase('tr') && cleaned !== cleaned.toLocaleLowerCase('tr')) {
            if (capslockCounts[m.sender] !== undefined) {
                capslockCounts[m.sender]++;
            }
        }
    });

    // Profanity count calculation
    const blacklistWords = new Set(decodeURIComponent(escape(atob(ENCODED_BLACKLIST))).split(","));
    const profanityCounts = {};
    sendersList.forEach(s => profanityCounts[s] = 0);
    parsedMessages.forEach(m => {
        splitWords(m.content).forEach(w => {
            if (blacklistWords.has(w)) {
                if (profanityCounts[m.sender] !== undefined) {
                    profanityCounts[m.sender]++;
                }
            }
        });
    });

    // L. Pairwise interactions (Conversation session between 2 people)
    // A session: >= 5 messages between 2 users, no 3rd person interruption, <= 30min gap
    const pairwiseExchanges = {};
    const thirtyMin = 30 * 60 * 1000;

    let currentPair = null;
    let lastMsgTime = null;
    let prevSender = null;
    let sessionCount = 0;

    sortedMsgs.forEach((m, i) => {
        const sender = m.sender;
        const time = m.date.getTime();

        if (currentPair) {
            if (currentPair.includes(sender)) {
                if (lastMsgTime !== null && (time - lastMsgTime) <= thirtyMin) {
                    sessionCount++;
                    lastMsgTime = time;
                    prevSender = sender;
                    return; // Acts as continue inside forEach callback
                } else {
                    if (sessionCount >= 5) {
                        const pairKey = currentPair.join(" & ");
                        pairwiseExchanges[pairKey] = (pairwiseExchanges[pairKey] || 0) + 1;
                    }
                    currentPair = null;
                    sessionCount = 0;
                }
            } else {
                if (sessionCount >= 5) {
                    const pairKey = currentPair.join(" & ");
                    pairwiseExchanges[pairKey] = (pairwiseExchanges[pairKey] || 0) + 1;
                }
                currentPair = null;
                sessionCount = 0;
            }
        }

        if (!currentPair && prevSender && prevSender !== sender) {
            currentPair = [prevSender, sender].sort();
            sessionCount = 2;
            lastMsgTime = time;
        }
        prevSender = sender;
    });
    // Check trailing session
    if (currentPair && sessionCount >= 5) {
        const pairKey = currentPair.join(" & ");
        pairwiseExchanges[pairKey] = (pairwiseExchanges[pairKey] || 0) + 1;
    }

    // M. Mentions Analysis
    const totalMentionsReceived = {};
    const totalMentionsGiven = {};
    const mentionMatrix = {};

    sendersList.forEach(s => {
        totalMentionsReceived[s] = 0;
        totalMentionsGiven[s] = 0;
        mentionMatrix[s] = {};
        sendersList.forEach(other => mentionMatrix[s][other] = 0);
    });

    sendersList.forEach(user => {
        const userLower = user.toLocaleLowerCase('tr');
        let nameParts = userLower.split(/\s+/).filter(p => p.length >= 3);
        if (nameParts.length === 0) nameParts = [userLower];

        // Escape regex patterns safely (escape base and last individually before appending quantifier)
        const patterns = nameParts.map(p => {
            if (p.length === 0) return '';
            const baseChar = p.slice(0, -1);
            const lastChar = p.slice(-1);
            const baseEscaped = baseChar.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const lastEscaped = lastChar.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            // Unicode-aware word edges (\b is ASCII-only and never matches around names like "Çağla" or "Ömür")
            return `(?<![\\p{L}\\p{N}_])${baseEscaped}${lastEscaped}+[\\p{L}\\p{N}_']{0,2}(?![\\p{L}\\p{N}_])`;
        }).filter(pat => pat.length > 0);

        if (patterns.length === 0) return;

        const pattern = new RegExp(patterns.join('|'), 'iu');

        parsedMessages.forEach(m => {
            if (m.sender !== user && pattern.test(m.content.toLocaleLowerCase('tr'))) {
                totalMentionsReceived[user]++;
                totalMentionsGiven[m.sender]++;
                mentionMatrix[m.sender][user]++;
            }
        });
    });

    // N. Streaks (Longest silence and longest daily streaks)
    const longestSilence = {};
    const dailyStreaks = {};

    sendersList.forEach(user => {
        const userMsgs = sortedMsgs.filter(m => m.sender === user);

        // Silence in full calendar days
        if (userMsgs.length > 1) {
            const uniqueDates = [...new Set(userMsgs.map(m => getLocalJSDateString(m.date)))].sort();
            let maxGapDays = 0;
            for (let i = 1; i < uniqueDates.length; i++) {
                const d1 = new Date(uniqueDates[i - 1]);
                const d2 = new Date(uniqueDates[i]);
                const diffDays = Math.round((d2 - d1) / (24 * 3600 * 1000));
                if (diffDays > maxGapDays) maxGapDays = diffDays;
            }
            longestSilence[user] = maxGapDays;
        } else {
            longestSilence[user] = 0;
        }

        // Consecutive days streak
        if (userMsgs.length > 0) {
            const uniqueDates = [...new Set(userMsgs.map(m => getLocalJSDateString(m.date)))].sort();
            let currentStreak = 1;
            let maxStreak = 1;

            for (let i = 1; i < uniqueDates.length; i++) {
                const d1 = new Date(uniqueDates[i - 1]);
                const d2 = new Date(uniqueDates[i]);
                const diffDays = Math.round((d2 - d1) / (24 * 3600 * 1000));

                if (diffDays === 1) {
                    currentStreak++;
                    if (currentStreak > maxStreak) maxStreak = currentStreak;
                } else {
                    currentStreak = 1;
                }
            }
            dailyStreaks[user] = maxStreak;
        } else {
            dailyStreaks[user] = 0;
        }
    });

    // O. Unique Words
    const uniqueWordCounts = {};
    sendersList.forEach(s => {
        const words = parsedMessages
            .filter(m => m.sender === s)
            .flatMap(m => splitWords(m.content))
            .filter(w => w.length >= 3);
        uniqueWordCounts[s] = new Set(words).size;
    });

    // P. Weekly Champions
    // Calculate week key (Sunday frequency format)
    const getSundayOfWeek = (date) => {
        const d = new Date(date);
        const day = d.getDay();
        const diff = d.getDate() - day + (day === 0 ? 0 : 7); // next Sunday
        return getLocalJSDateString(new Date(d.setDate(diff)));
    };

    const weeklySenderActivity = {}; // { "week-date": { "sender": count } }
    parsedMessages.forEach(m => {
        const weekKey = getSundayOfWeek(m.date);
        if (!weeklySenderActivity[weekKey]) weeklySenderActivity[weekKey] = {};
        weeklySenderActivity[weekKey][m.sender] = (weeklySenderActivity[weekKey][m.sender] || 0) + 1;
    });

    const weeklyWinners = {};
    for (let week in weeklySenderActivity) {
        let maxCount = -1;
        let winner = null;
        for (let s in weeklySenderActivity[week]) {
            if (weeklySenderActivity[week][s] > maxCount) {
                maxCount = weeklySenderActivity[week][s];
                winner = s;
            }
        }
        weeklyWinners[week] = winner;
    }

    const weeklyWinCounts = {};
    sendersList.forEach(s => weeklyWinCounts[s] = 0);
    Object.values(weeklyWinners).forEach(w => {
        if (weeklyWinCounts[w] !== undefined) weeklyWinCounts[w]++;
    });

    // Q. Weekly Timeline
    const weeklyTimelineCounts = {};
    parsedMessages.forEach(m => {
        const weekKey = getSundayOfWeek(m.date);
        weeklyTimelineCounts[weekKey] = (weeklyTimelineCounts[weekKey] || 0) + 1;
    });
    const sortedWeeks = Object.keys(weeklyTimelineCounts).sort();
    const weeklyTimelineData = sortedWeeks.map(w => weeklyTimelineCounts[w]);

    // R. Top Words counts (Exclude blacklist)
    const allWordsCounts = newCounter();
    parsedMessages.forEach(m => {
        const words = splitWords(m.content).filter(w => w.length >= 3);
        words.forEach(w => {
            if (!blacklistWords.has(w)) {
                allWordsCounts[w] = (allWordsCounts[w] || 0) + 1;
            }
        });
    });
    const topWords = Object.entries(allWordsCounts)
        .filter(([w]) => !DM_WORD_STOPWORDS.has(w))
        .sort((a, b) => b[1] - a[1])
        .slice(0, 10);

    // Helpers to find winner / champion
    const getChampion = (map) => {
        let maxVal = -1;
        let winner = "Yok";
        for (let s in map) {
            const val = parseFloat(map[s]);
            if (val > maxVal) {
                maxVal = val;
                winner = s;
            }
        }
        // Nobody did it at all (e.g. no caps-lock message): no winner instead of an alphabetical one
        if (maxVal <= 0) return { winner: "Yok", count: 0 };
        return { winner, count: maxVal };
    };

    // Calculate profanity densities (words per profanity)
    const profanityDensities = {};
    sendersList.forEach(s => {
        const words = wordCounts[s] || 0;
        const prof = profanityCounts[s] || 0;
        if (prof > 0) {
            profanityDensities[s] = parseFloat((words / prof).toFixed(1));
        } else {
            profanityDensities[s] = 0;
        }
    });

    // Ascending sort (lowest density value first, meaning most frequent profanity)
    const activeProfanityUsers = Object.entries(profanityDensities)
        .filter(([user, density]) => density > 0 && profanityCounts[user] > 0)
        .sort((a, b) => a[1] - b[1]);

    let profanityWinner = "Yok";
    let profanityWinnerCount = 0;
    if (activeProfanityUsers.length > 0) {
        profanityWinner = activeProfanityUsers[0][0];
        profanityWinnerCount = activeProfanityUsers[0][1];
    }

    return {
        messages: parsedMessages,
        senders: sendersList,
        isDM: detectedIsDM,
        groupName: groupName,
        periodLabel: period === "2026" ? "2026" : "All Time",
        multiYear,
        totalUsers,
        dailyAvg,
        firstDateStr: formatDateForPdf(firstMsgDate),
        lastDateStr: formatDateForPdf(lastMsgDate),
        topMembers,
        stats: {
            totalMessages: parsedMessages.length,
            messageCounts,
            monthlyCounts,
            monthLabels,
            dailyCounts,
            dayLabels,
            hourlyCounts,
            nightOwls,
            morningBirds,
            firstMsgWinnerCounts,
            firstResponderCounts,
            starterCounts,
            continuationAverages,
            avgWords,
            topEmojis,
            punctuationCounts,
            capslockCounts,
            pairwiseExchanges,
            mentionMatrix,
            silentStartHour,
            silentEndHour,
            longestSilence,
            dailyStreaks,
            uniqueWordCounts,
            weeklyWinners,
            weeklyWinCounts,
            sortedWeeks,
            weeklyTimelineData,
            profanityCounts,
            profanityDensities,
            allWordsCounts,
            topWords,
            champions: {
                message: getChampion(messageCounts),
                nightOwl: getChampion(nightOwls),
                morningBird: getChampion(morningBirds),
                firstMsg: getChampion(firstMsgWinnerCounts),
                firstResponder: getChampion(firstResponderCounts),
                starter: getChampion(starterCounts),
                continuation: getChampion(continuationAverages),
                avgWords: getChampion(avgWords),
                caps: getChampion(capslockCounts),
                silence: getChampion(longestSilence),
                streak: getChampion(dailyStreaks),
                uniqueWords: getChampion(uniqueWordCounts),
                weeklyWins: getChampion(weeklyWinCounts),
                profanity: { winner: profanityWinner, count: profanityWinnerCount }
            }
        }
    };
}

