// Top words slide: one slide per minimum word length ("all words" = 3+ letters, and 4+ letters)
const DM_WORD_STOPWORDS = new Set([
    've', 'bir', 'bu', 'da', 'de', 'mi', 'mu', 'mü', 'için', 'ile', 'o', 'ne', 'var',
    'ya', 'çok', 'ben', 'sen', 'biz', 'siz', 'onlar', 'daha', 'en', 'şey', 'gibi',
    'ama', 'veya', 'olan', 'oldu', 'yok', 'ki', 'mı', 'nasıl', 'neden', 'nerede',
    'kim', 'şimdi', 'sonra', 'var', 'yani', 'falan', 'işte', 'hani', 'böyle', 'öyle',
    'şu', 'bana', 'sana', 'ona', 'bunu', 'şunu', 'onu', 'the', 'a', 'an', 'and', 'or',
    'is', 'are', 'was', 'were', 'be', 'been', 'being', 'have', 'has', 'had', 'do',
    'does', 'did', 'will', 'would', 'could', 'should', 'may', 'might', 'can', 'to',
    'message', 'deleted', 'omitted', 'media', 'image', 'video', 'audio', 'sticker',
    'null', 'undefined', 'edited', 'medya', 'dahil', 'edilmedi', 'mesaj', 'düzenlendi'
]);

function renderTopWordsSlide(el, data, minLen, label) {
    const rankList = (words) => words.map((w, idx) => `
        <div class="rank-item" style="padding: 0.35rem 0;">
            <span>${idx + 1}. "${esc(w[0])}"</span>
            <strong>${w[1]}</strong>
        </div>
    `).join('') || '<p>Kelime yok.</p>';

    if (data.isDM) {
        const topWordsOf = (user) => {
            const counts = newCounter();
            data.messages.forEach(m => {
                if (m.sender !== user) return;
                splitWords(m.content).forEach(w => {
                    if (w.length >= minLen && !DM_WORD_STOPWORDS.has(w)) counts[w] = (counts[w] || 0) + 1;
                });
            });
            return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 5);
        };
        const [u1, u2] = data.senders;
        el.innerHTML = `
            <div class="slide-split-layout" style="grid-template-columns: 1fr 1fr;">
                <div style="border-right: 1px solid rgba(23, 23, 23, 0.1); padding-right: 1.5rem;">
                    <span class="slide-winner-title" style="display: block; margin-bottom: 0.75rem;">${esc(u1)}</span>
                    <div class="rank-list">${rankList(topWordsOf(u1))}</div>
                </div>
                <div style="padding-left: 1.5rem;">
                    <span class="slide-winner-title" style="display: block; margin-bottom: 0.75rem; color: #171717;">${esc(u2)}</span>
                    <div class="rank-list">${rankList(topWordsOf(u2))}</div>
                </div>
            </div>
        `;
        return;
    }

    const topWords = Object.entries(data.stats.allWordsCounts)
        .filter(([word]) => word.length >= minLen && !DM_WORD_STOPWORDS.has(word))
        .sort((a, b) => b[1] - a[1])
        .slice(0, 10);

    el.innerHTML = `
        <div class="slide-split-layout">
            <div class="slide-left">
                <span class="slide-winner-title">Favori Kelime</span>
                <h2 class="slide-winner-name">"${esc(topWords[0]?.[0] || '-')}"</h2>
                <p class="slide-winner-detail">${label} içinde grubun en sık kullandığı kelime.</p>
            </div>
            <div class="slide-right" style="flex-direction: column; align-items: stretch;">
                <span class="slide-winner-title" style="margin-bottom: 0.5rem; font-size: 0.8rem; display: block;">${label}</span>
                <div class="rank-list" style="max-height: none;">${rankList(topWords)}</div>
            </div>
        </div>
    `;
}

