    "emoji_punctuation": {
        id: "emoji_punctuation",
        title: "Emoji & Noktalama Kullanımı",
        render: (el, data) => {
            const countEmojis = (text) => {
                const matches = text.match(EMOJI_REGEX);
                return matches ? matches.length : 0;
            };
            const countPunctuation = (text) => {
                let count = 0;
                const multiMarks = ['...', ':)', ':(', ':D', 'xD', '<3'];
                multiMarks.forEach(m => {
                    let pos = text.indexOf(m);
                    while (pos !== -1) {
                        count++;
                        pos = text.indexOf(m, pos + m.length);
                    }
                });
                for (let char of text) {
                    if (char === '!' || char === '?') {
                        count++;
                    }
                }
                return count;
            };

            const emojiCounts = {};
            const punctCounts = {};
            data.senders.forEach(s => {
                emojiCounts[s] = 0;
                punctCounts[s] = 0;
            });
            data.messages.forEach(m => {
                if (emojiCounts[m.sender] !== undefined) {
                    emojiCounts[m.sender] += countEmojis(m.content);
                    punctCounts[m.sender] += countPunctuation(m.content);
                }
            });

            const sortedEmojiWinners = Object.entries(emojiCounts).sort((a, b) => b[1] - a[1]);
            const sortedPunctWinners = Object.entries(punctCounts).sort((a, b) => b[1] - a[1]);

            const emojiWinnerUser = sortedEmojiWinners[0]?.[0] || '-';
            const emojiWinnerVal = sortedEmojiWinners[0]?.[1] || 0;

            const punctWinnerUser = sortedPunctWinners[0]?.[0] || '-';
            const punctWinnerVal = sortedPunctWinners[0]?.[1] || 0;

            el.innerHTML = `
                <div class="slide-methodology-layout">
                    <div class="methodology-card">
                        <h4>EMOJİ KRALI/KRALİÇESİ</h4>
                        <p style="font-size: 2rem; font-weight: 800; color: #171717; margin: 0.5rem 0;">${esc(emojiWinnerUser)}</p>
                        <p style="font-size: 1.2rem; font-weight: 700; color: #9B1C31;">${esc(emojiWinnerVal)} emoji</p>
                    </div>
                    <div class="methodology-card">
                        <h4>NOKTALAMA USTASI</h4>
                        <p style="font-size: 2rem; font-weight: 800; color: #171717; margin: 0.5rem 0;">${esc(punctWinnerUser)}</p>
                        <p style="font-size: 1.2rem; font-weight: 700; color: #9B1C31;">${esc(punctWinnerVal)} işaret</p>
                    </div>
                </div>
            `;
        }
    },
