    "unique_words": {
        id: "unique_words",
        title: "Kendine Özgü Kelimeler",
        render: (el, data) => {
            const getUniqueWordsPerUser = () => {
                const stopWords = new Set([
                    've', 'bir', 'bu', 'da', 'de', 'mi', 'mu', 'mü', 'için', 'ile', 'o', 'ne', 'var',
                    'ya', 'çok', 'ben', 'sen', 'biz', 'siz', 'onlar', 'daha', 'en', 'şey', 'gibi',
                    'ama', 'veya', 'olan', 'oldu', 'yok', 'ki', 'mı', 'nasıl', 'neden', 'nerede',
                    'kim', 'şimdi', 'sonra', 'var', 'yani', 'falan', 'işte', 'hani', 'böyle', 'öyle',
                    'şu', 'bana', 'sana', 'ona', 'bunu', 'şunu', 'onu', 'the', 'a', 'an', 'and', 'or',
                    'is', 'are', 'was', 'were', 'be', 'been', 'being', 'have', 'has', 'had', 'do',
                    'does', 'did', 'will', 'would', 'could', 'should', 'may', 'might', 'can', 'to',
                    'message', 'deleted', 'omitted', 'media', 'image', 'video', 'audio', 'sticker',
                    'null', 'undefined', 'edited', 'medya', 'dahil', 'edilmedi', 'mesaj', 'düzenlendi'
                ]);
                const wordCounts = {};
                const totalWords = {};
                const globalWordCounts = newCounter();
                data.senders.forEach(s => {
                    wordCounts[s] = newCounter();
                    totalWords[s] = 0;
                });
                data.messages.forEach(m => {
                    if (wordCounts[m.sender] !== undefined) {
                        splitWords(m.content)
                            .forEach(w => {
                                if (w.length >= 3 && !stopWords.has(w)) {
                                    wordCounts[m.sender][w] = (wordCounts[m.sender][w] || 0) + 1;
                                    totalWords[m.sender]++;
                                    globalWordCounts[w] = (globalWordCounts[w] || 0) + 1;
                                }
                            });
                    }
                });
                const uniqueWords = {};
                data.senders.forEach(user => {
                    const myWords = wordCounts[user];
                    const myTotal = totalWords[user];
                    if (myTotal === 0) return;
                    const candidates = [];
                    for (let word in myWords) {
                        const myCount = myWords[word];
                        if (myCount < 2) continue;
                        const otherCount = globalWordCounts[word] - myCount;
                        let otherTotal = 0;
                        data.senders.forEach(other => {
                            if (other !== user) otherTotal += totalWords[other];
                        });
                        const myFreq = myCount / myTotal;
                        const otherFreq = otherTotal > 0 ? (otherCount / otherTotal) : 0;
                        const score = otherFreq > 0 ? (myFreq / otherFreq) : (myFreq * 100);
                        candidates.push({ word, score });
                    }
                    uniqueWords[user] = candidates.sort((a, b) => b.score - a.score).slice(0, 3).map(c => c.word);
                });
                return uniqueWords;
            };

            const uniqueWords = getUniqueWordsPerUser();
            const cardsHTML = Object.entries(uniqueWords).map(([user, words]) => `
                <div class="methodology-card">
                    <h4>${esc(user)}</h4>
                    ${words.map(w => `<p style="font-size: 0.95rem; font-style: italic; color: #171717; margin: 0.25rem 0;">• ${esc(w)}</p>`).join('')}
                </div>
            `).join('');

            el.innerHTML = `
                <div class="slide-methodology-layout" style="grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));">
                    ${cardsHTML}
                </div>
            `;
        }
    },
