// Stepper / Presentation Deck Manager
function renderSlide(index) {
    if (!calculatedStats) return;

    // Clear active slide graphs
    activeCharts.forEach(c => c.destroy());
    activeCharts = [];

    const activeSlideEl = document.getElementById("active-slide");
    activeSlideEl.innerHTML = ""; // reset slide layout

    const slideObj = slidesList[index];
    if (!slideObj) return;

    // Set Presentation Header Title
    document.getElementById("deck-progress").innerText = `Slide ${index + 1} / ${slidesList.length}`;

    // Create Header element inside slide card
    const header = document.createElement("div");
    header.className = "slide-header";
    header.innerText = typeof slideObj.title === "function" ? slideObj.title(calculatedStats) : slideObj.title;
    if (slideObj.hideHeader) header.style.display = "none";
    activeSlideEl.appendChild(header);

    // Create Content element
    const content = document.createElement("div");
    content.className = "slide-content-box";
    activeSlideEl.appendChild(content);

    // Call individual rendering method
    slideObj.render(content, calculatedStats);
}

function handleDeckNavigation(direction) {
    if (!calculatedStats) return;

    currentSlideIndex += direction;
    if (currentSlideIndex < 0) {
        currentSlideIndex = slidesList.length - 1;
    } else if (currentSlideIndex >= slidesList.length) {
        currentSlideIndex = 0;
    }
    renderSlide(currentSlideIndex);
}

function isFullscreen() {
    return document.getElementById("dashboard-area").classList.contains("fullscreen-active");
}

function setFullscreen(on) {
    const area = document.getElementById("dashboard-area");
    if (on === isFullscreen()) return;

    area.classList.toggle("fullscreen-active", on);
    document.body.style.overflow = on ? "hidden" : "";
    document.getElementById("deck-fullscreen-btn").innerText = on ? "✖ Küçült" : "📺 Tam Ekran";

    if (calculatedStats) renderSlide(currentSlideIndex);
    if (!on && !area.classList.contains("hidden")) {
        area.scrollIntoView({ block: "start" });
    }
}

// File Handlers & Event Binding
function setupEventListeners() {
    const fileInput = document.getElementById("file-upload");
    fileInput.addEventListener("change", (e) => {
        handleFiles(e.target.files);
    });

    const dropArea = document.getElementById("drop-area");

    const preventDefaults = (e) => {
        e.preventDefault();
        e.stopPropagation();
    };

    dropArea.addEventListener("dragenter", preventDefaults);
    dropArea.addEventListener("dragover", preventDefaults);
    dropArea.addEventListener("dragleave", preventDefaults);
    dropArea.addEventListener("drop", (e) => {
        preventDefaults(e);
        handleFiles(e.dataTransfer.files);
    });

    // Analysis period (All Time / 2026): re-run the analysis on the already loaded chat
    document.querySelectorAll('input[name="period"]').forEach(radio => {
        radio.addEventListener("change", () => {
            if (!radio.checked) return;
            selectedPeriod = radio.value;
            triggerDashboardReRender(true);
        });
    });

    // "Nasıl Yaparım?" toggle
    document.getElementById("how-to-btn").addEventListener("click", () => {
        document.getElementById("how-to-content").classList.toggle("hidden");
    });

    // "Gizlilik Hakkında" toggle
    document.getElementById("privacy-btn").addEventListener("click", () => {
        document.getElementById("privacy-content").classList.toggle("hidden");
    });

    // Presentation deck button click listeners
    document.getElementById("deck-prev-btn").addEventListener("click", () => handleDeckNavigation(-1));
    document.getElementById("deck-next-btn").addEventListener("click", () => handleDeckNavigation(1));

    // Keyboard support for presentation slide navigation
    document.addEventListener("keydown", (e) => {
        // Don't hijack arrow keys while the user is typing a name
        if (e.target.matches('input[type="text"], textarea')) return;
        if (calculatedStats && !document.getElementById("dashboard-area").classList.contains("hidden")) {
            if (e.key === "ArrowLeft") handleDeckNavigation(-1);
            if (e.key === "ArrowRight") handleDeckNavigation(1);
            if (e.key === "Escape") setFullscreen(false);
        }
    });

    // Touch: horizontal swipe on the slide changes slides (vertical swipes still scroll)
    const slideViewport = document.querySelector(".slide-viewport");
    let touchStart = null;
    slideViewport.addEventListener("touchstart", (e) => {
        touchStart = e.touches.length === 1 ? { x: e.touches[0].clientX, y: e.touches[0].clientY } : null;
    }, { passive: true });
    slideViewport.addEventListener("touchend", (e) => {
        if (!touchStart || !calculatedStats) return;
        const dx = e.changedTouches[0].clientX - touchStart.x;
        const dy = e.changedTouches[0].clientY - touchStart.y;
        touchStart = null;
        if (Math.abs(dx) > 50 && Math.abs(dx) > Math.abs(dy) * 1.5) handleDeckNavigation(dx < 0 ? 1 : -1);
    }, { passive: true });

    // Fullscreen and PDF deck actions
    document.getElementById("deck-fullscreen-btn").addEventListener("click", () => {
        setFullscreen(!isFullscreen());
    });

    document.getElementById("deck-names-btn").addEventListener("click", () => {
        setFullscreen(false);
        document.getElementById("user-mapping-area").scrollIntoView({ behavior: "smooth", block: "start" });
    });

    document.getElementById("deck-pdf-btn").addEventListener("click", downloadJsPdf);

    document.getElementById("sample-btn").addEventListener("click", loadSampleChat);
}

function handleFiles(files) {
    if (files.length > 0) {
        loadChatFile(files.item(0));
    } else {
        resetState();
    }
}

// "Örnek sunum oluştur": analyse a generated, fictional group chat (see sample-chat.js)
function loadSampleChat() {
    const text = generateSampleChat();
    loadChatFile(new File([text], `WhatsApp Sohbeti - ${SAMPLE_GROUP_NAME} (örnek).txt`, { type: "text/plain" }));
}

function loadChatFile(file) {
    selectedFile = file;
    document.getElementById("filename").innerText = selectedFile.name;
    document.getElementById("file-info").classList.remove("hidden");

    // Hide previous results to clean up space
    setFullscreen(false);
    document.getElementById("user-mapping-area").classList.add("hidden");
    document.getElementById("dashboard-area").classList.add("hidden");

    // Show Stepper and trigger stream parsing
    document.getElementById("stepper-container").classList.remove("hidden");
    updateStepUI("step-parse", "active");
    updateStepUI("step-analyze", "pending");
    updateStepUI("step-charts", "pending");
    updateLineUI("line-parse-analyze", false);
    updateLineUI("line-analyze-charts", false);

    setTimeout(() => startFileStreaming(selectedFile), 100);
}

function resetState() {
    selectedFile = null;
    parsedData = null;
    calculatedStats = null;

    setFullscreen(false);
    document.getElementById("user-mapping-area").classList.add("hidden");
    document.getElementById("user-mapping-list").innerHTML = "";
    document.getElementById("stepper-container").classList.add("hidden");
    document.getElementById("dashboard-area").classList.add("hidden");
}

async function startFileStreaming(file) {
    try {
        setStepperDetail("Dosya okunuyor ve satırlara ayrılıyor...");

        let textContent = "";
        if (file.name.toLowerCase().endsWith(".zip")) {
            setStepperDetail("ZIP arşivi açılıyor...");
            const arrayBuf = await file.arrayBuffer();
            await loadJSZipIfNeeded();

            const zip = await JSZip.loadAsync(arrayBuf);
            const txtFiles = Object.keys(zip.files).filter(name => name.toLowerCase().endsWith(".txt") && !name.startsWith("__MACOSX"));
            if (txtFiles.length === 0) {
                throw new Error("ZIP dosyası içinde .txt dosyası bulunamadı.");
            }
            textContent = await zip.files[txtFiles[0]].async("text");
        } else {
            textContent = await file.text();
        }

        updateStepUI("step-parse", "completed");
        updateLineUI("line-parse-analyze", true);
        updateStepUI("step-analyze", "active");
        setStepperDetail("İstatistikler hesaplanıyor, sohbet yapısı çıkartılıyor...");

        // Emulate streaming/chunk loading for progress indicator
        setTimeout(() => {
            try {
                const { lines: parsedLines, groupName } = parseChatText(textContent);

                parsedData = {
                    messages: parsedLines.map(p => [p.timestamp, p.sender, p.content]),
                    columns: ['timestamp', 'sender', 'content'],
                    group_name: groupName
                };

                // Name list always covers the whole chat, whichever period is selected
                const allTimeAnalysis = calculateStats(parsedLines, groupName, {}, "all");
                if (!allTimeAnalysis) {
                    setStepperDetail("Hata: Geçerli mesaj bulunamadı.");
                    updateStepUI("step-analyze", "pending");
                    return;
                }
                populateUserMappingUI(allTimeAnalysis.senders);

                const analysis = selectedPeriod === "all" ? allTimeAnalysis : calculateStats(parsedLines, groupName, {}, selectedPeriod);
                updateStepUI("step-analyze", "completed");
                if (!analysis) {
                    showNoDataForPeriod();
                    return;
                }

                updateLineUI("line-analyze-charts", true);
                updateStepUI("step-charts", "completed");
                setStepperDetail("Analiz tamamlandı! Sunum tam ekranda açıldı. İsimleri düzeltmek için sunumdaki \"✏️ İsimler\" butonunu kullanabilirsiniz.");

                // Display slide deck as the main result, directly in fullscreen
                setupAndDisplaySlideDeck(analysis);
                setFullscreen(true);
            } catch (innerError) {
                console.error(innerError);
                setStepperDetail("Analiz sırasında hata oluştu: " + innerError.message);
                updateStepUI("step-analyze", "pending");
            }
        }, 150);

    } catch (e) {
        console.error(e);
        setStepperDetail("Hata oluştu: " + e.message);
        updateStepUI("step-parse", "pending");
    }
}

async function loadJSZipIfNeeded() {
    if (typeof JSZip === "undefined") {
        setStepperDetail("ZIP desteği yükleniyor...");
        return new Promise((resolve, reject) => {
            const script = document.createElement("script");
            script.src = "https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js";
            script.integrity = "sha384-+mbV2IY1Zk/X1p/nWllGySJSUN8uMs+gUAN10Or95UBH0fpj6GfKgPmgC5EXieXG";
            script.crossOrigin = "anonymous";
            script.onload = resolve;
            script.onerror = reject;
            document.head.appendChild(script);
        });
    }
}

function populateUserMappingUI(senders) {
    const container = document.getElementById("user-mapping-list");
    container.innerHTML = "";

    senders.forEach(sender => {
        const div = document.createElement("div");
        div.className = "user-item";

        const label = document.createElement("label");
        label.innerText = sender;
        label.title = sender;

        const inputField = document.createElement("input");
        inputField.type = "text";
        inputField.value = sender;
        inputField.setAttribute("data-original", sender);
        inputField.className = "user-map-input";

        // Handle live name updates in dashboard
        inputField.addEventListener("input", debounce(() => {
            triggerDashboardReRender();
        }, 500));

        div.appendChild(label);
        div.appendChild(inputField);
        container.appendChild(div);
    });

    document.getElementById("user-mapping-area").classList.remove("hidden");
}

function showNoDataForPeriod() {
    setFullscreen(false);
    calculatedStats = null;
    document.getElementById("dashboard-area").classList.add("hidden");
    updateStepUI("step-charts", "pending");
    setStepperDetail("Bu sohbette 2026 yılına ait mesaj bulunamadı. \"All Time\" seçeneğiyle tüm sohbeti analiz edebilirsiniz.");
}

function triggerDashboardReRender(openFullscreen = false) {
    if (!parsedData) return;

    const userMap = {};
    const inputs = document.querySelectorAll(".user-map-input");
    inputs.forEach(inp => {
        const original = inp.getAttribute("data-original");
        const newName = inp.value.trim();
        if (newName && newName !== original) {
            userMap[original] = newName;
        }
    });

    const parsedLines = parsedData.messages.map(m => ({
        timestamp: m[0],
        sender: m[1],
        content: m[2]
    }));

    const analysis = calculateStats(parsedLines, parsedData.group_name, userMap);
    if (!analysis) {
        showNoDataForPeriod();
        return;
    }
    updateStepUI("step-charts", "completed");
    setupAndDisplaySlideDeck(analysis);
    if (openFullscreen) setFullscreen(true);
}

// Configures and starts presentation slide deck viewer
function setupAndDisplaySlideDeck(analysis) {
    calculatedStats = analysis;

    // Select slides based on Group or DM mode (matching python lists 1:1)
    const ids = analysis.isDM ? DM_SLIDE_IDS : GROUP_SLIDE_IDS;
    slidesList = ids.map(id => SLIDES_MAP[id]).filter(slide => slide !== undefined);

    currentSlideIndex = 0;

    // Show deck area
    document.getElementById("dashboard-area").classList.remove("hidden");
    document.getElementById("dashboard-area").style.display = "block";

    // Render first slide
    renderSlide(currentSlideIndex);
}

async function downloadJsPdf() {
    if (!calculatedStats) return;

    const btn = document.getElementById("deck-pdf-btn");
    const originalText = btn.innerText;
    btn.innerText = "Hazırlanıyor...";
    btn.disabled = true;

    try {
        if (typeof html2pdf === "undefined") {
            setStepperDetail("Slayt PDF kütüphanesi yükleniyor...");
            await new Promise((resolve, reject) => {
                const script = document.createElement("script");
                script.src = "https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js";
                script.integrity = "sha384-Yv5O+t3uE3hunW8uyrbpPW3iw6/5/Y7HitWJBLgqfMoA36NogMmy+8wWZMpn3HWc";
                script.crossOrigin = "anonymous";
                script.onload = resolve;
                script.onerror = reject;
                document.head.appendChild(script);
            });
        }

        setStepperDetail("Slaytlar PDF formatına dönüştürülüyor...");

        // Off-screen positioning lives on a wrapper: html2pdf clones the element it captures,
        // so offsets set on that element itself would push the clone out of frame (blank PDF).
        const offscreenWrapper = document.createElement("div");
        offscreenWrapper.style.position = "fixed";
        offscreenWrapper.style.left = "-20000px";
        offscreenWrapper.style.top = "0";
        const printContainer = document.createElement("div");
        printContainer.style.width = "1024px";
        offscreenWrapper.appendChild(printContainer);
        document.body.appendChild(offscreenWrapper);
        const slideEls = [];

        const tempCharts = [];

        for (let i = 0; i < slidesList.length; i++) {
            const slideWrapper = document.createElement("div");
            slideWrapper.className = "slide-card pdf-slide";
            slideWrapper.style.width = "1024px";
            slideWrapper.style.height = "576px";
            slideWrapper.style.display = "flex";
            slideWrapper.style.flexDirection = "column";
            slideWrapper.style.padding = "2.2rem 3rem";
            slideWrapper.style.background = "#F7F6F2";
            slideWrapper.style.color = "#171717";
            slideWrapper.style.borderRadius = "0px";
            slideWrapper.style.boxShadow = "none";
            slideWrapper.style.border = "1px solid #171717";

            const slideObj = slidesList[i];

            const header = document.createElement("div");
            header.className = "slide-header";
            header.innerText = typeof slideObj.title === "function" ? slideObj.title(calculatedStats) : slideObj.title;
            if (slideObj.hideHeader) header.style.display = "none";
            slideWrapper.appendChild(header);

            const content = document.createElement("div");
            content.className = "slide-content-box";
            content.style.flex = "1";
            content.style.position = "relative";
            slideWrapper.appendChild(content);

            printContainer.appendChild(slideWrapper);
            slideEls.push(slideWrapper);

            const originalGetElementById = document.getElementById;
            document.getElementById = function (id) {
                if (id === "slide-chart-canvas") {
                    let canvas = content.querySelector("#slide-chart-canvas");
                    if (!canvas) {
                        canvas = document.createElement("canvas");
                        canvas.id = "slide-chart-canvas";
                        content.appendChild(canvas);
                    }
                    return canvas;
                }
                return originalGetElementById.call(document, id);
            };

            slideObj.render(content, calculatedStats);
            document.getElementById = originalGetElementById;

            const createdChart = activeCharts.pop();
            if (createdChart) {
                tempCharts.push(createdChart);
            }
        }

        await new Promise(resolve => setTimeout(resolve, 800));

        const options = {
            margin: 0,
            filename: `${calculatedStats.groupName || 'sohbet'}_istatistikleri.pdf`,
            image: { type: 'jpeg', quality: 0.95 },
            // scrollX/scrollY: 0 — otherwise the page's scroll offset shifts every captured slide down (white band on top)
            html2canvas: { scale: 2, logging: false, scrollX: 0, scrollY: 0, backgroundColor: '#F7F6F2' },
            jsPDF: { unit: 'px', format: [1024, 576], orientation: 'landscape', hotfixes: ['px_scaling'] }
        };

        // Capture one slide per page (one huge canvas for all slides exceeds browser canvas limits)
        let pdfJob = html2pdf().set(options).from(slideEls[0]).toPdf();
        for (let i = 1; i < slideEls.length; i++) {
            pdfJob = pdfJob.get('pdf')
                .then(pdf => pdf.addPage([1024, 576], 'landscape'))
                .from(slideEls[i]).toContainer().toCanvas().toPdf();
        }
        await pdfJob.save();

        tempCharts.forEach(c => c.destroy());
        document.body.removeChild(offscreenWrapper);
        setStepperDetail("Slayt PDF dosyası başarıyla indirildi.");
    } catch (err) {
        console.error(err);
        setStepperDetail("Slayt PDF indirme hatası: " + err.message);
    } finally {
        btn.innerText = originalText;
        btn.disabled = false;
    }
}

// Debounce helper
function debounce(func, wait) {
    let timeout;
    return function executedFunction(...args) {
        const later = () => {
            clearTimeout(timeout);
            func(...args);
        };
        clearTimeout(timeout);
        timeout = setTimeout(later, wait);
    };
}

// Run setup
window.addEventListener("DOMContentLoaded", () => {
    document.getElementById("drop-loading").classList.add("hidden");
    document.getElementById("drop-content").classList.remove("hidden");

    setupEventListeners();
});
